__global__ __launch_bounds__(512, 2) void rms_layernorm_forward_kernel_fp32(
    const float* __restrict__ X,
    const float* __restrict__ W,
    float* __restrict__ Y,
    float* __restrict__ r,
    const int N,
    const int D,
    const float eps
) {
