    const int tid = threadIdx.x;
    const int lane_id = tid & 31;
    const int warp_id = tid >> 5;
    const int num_warps = blockDim.x >> 5;

    if (row >= N) return;

    const float* x_row = X + row * D;
    float* y_row = Y + row * D;

    __shared__ float s_partial[32];

    // Compute sum of squares - unroll 4x for better ILP
    float sum_sq = 0.0f;
    int i = tid;
    for (; i + 3 < D; i += blockDim.x * 4) {
        float v0 = x_row[i];
        float v1 = x_row[i + blockDim.x];
        float v2 = x_row[i + blockDim.x * 2];
        float v3 = x_row[i + blockDim.x * 3];
        sum_sq += v0*v0 + v1*v1 + v2*v2 + v3*v3;
